const key=value=>typeof value==='string'?value.normalize('NFKC').replace(/\s+/g,''):'';
export function officialNutritionFor(name,code){
  return officialSupplements.find(entry=>entry.allowedMenuNames.some(value=>key(value)===key(name))&&
    (entry.matchMode==='exact-name'||entry.menuCodes.includes(String(code))));
}
export function officialGapFor(name,code){
  return officialGaps.find(entry=>key(entry.name)===key(name)&&(code==null||entry.code===String(code)));
}
